"use strict";(self.webpackChunkdg_knowlege_base=self.webpackChunkdg_knowlege_base||[]).push([[3009],{382:e=>{e.exports=JSON.parse('{"tag":{"label":"Playground","permalink":"/datagol-knowlegde-base-v1/docs/tags/playground","allTagsPath":"/datagol-knowlegde-base-v1/docs/tags","count":8,"items":[{"id":"Playgrounds/About Playground","title":"About Playground","description":"Playground is a versatile and interactive environment for users to engage with their data in an exploratory and flexible manner. This module acts as a space where you can connect to various data sources and play around with the information they contain.","permalink":"/datagol-knowlegde-base-v1/docs/Playgrounds/about-playground"},{"id":"Playgrounds/Connecting external data via Playground","title":"Connecting external data via Playground","description":"The Playground helps you connect and analyze data from different sources\u2014like combining employee data from MySQL with department info from Excel.","permalink":"/datagol-knowlegde-base-v1/docs/Playgrounds/connecting-external-data-via-playground"},{"id":"Playgrounds/Create queries in Playground","title":"Create queries in Playground","description":"You can create queries in Playground to interact with your data sources in two ways: directly writing SQL or leveraging AI assistance.","permalink":"/datagol-knowlegde-base-v1/docs/Playgrounds/create-queries-in-playground"},{"id":"Playgrounds/Creating queries in playground with SQL query","title":"Creating queries in playground with SQL query","description":"You can directly write SQL queries to retrieve and manipulate data from your connected data sources. This query can be saved and can be easily accessed and re-executed later.","permalink":"/datagol-knowlegde-base-v1/docs/Playgrounds/creating-queries-in-playground-with-sql-query"},{"id":"Playgrounds/Creating queries with AI assistance in Playground","title":"Creating queries with AI assistance in Playground","description":"You can use the SQL copilot from within Playground to generate, optimize, and debug SQL queries using natural language prompts. SQL copilot is integrated into Playground, which enhances the query writing experience by automatically generating SQL queries based on your data sources.","permalink":"/datagol-knowlegde-base-v1/docs/Playgrounds/create-queries-with-ai-assitance-in-playground"},{"id":"Playgrounds/Publishing queries from Playground","title":"Publishing queries from Playground","description":"If you want to use the query results in a workbook for further analysis or reporting, you can publish the results to a workspace. Once published, the results are available in a workbook from you can further visualize and analze the data.","permalink":"/datagol-knowlegde-base-v1/docs/Playgrounds/publishing-queries-from-playground1"},{"id":"Playgrounds/Running queries from Playground","title":"Running queries from Playground","description":".The Playground lets you retrieve and analyze specific data by writing and running SQL queries on your connected data sources.","permalink":"/datagol-knowlegde-base-v1/docs/Playgrounds/running-queries-from-playground"},{"id":"Playgrounds/Viewing published queries","title":"Viewing published queries","description":"1.  From the Home page, navigate to the Workspace where you have published your query.","permalink":"/datagol-knowlegde-base-v1/docs/Playgrounds/viewing-published-queries"}],"unlisted":false}}')}}]);